function validate([dictionary, sentence]) {
  if (!Array.isArray(dictionary) || dictionary.length < 1 || dictionary.length > 1000) return 'dictionary needs 1 to 1000 roots.';
  for (const root of dictionary) {
    if (typeof root !== 'string' || root.length < 1 || root.length > 100) return 'Each root has 1 to 100 letters.';
    if (!/^[a-z]+$/.test(root)) return 'Roots use lowercase letters only.';
  }
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 1000000) return 'sentence has 1 to 10^6 characters.';
  if (!/^[a-z]+( [a-z]+)*$/.test(sentence)) return 'sentence is lowercase words separated by single spaces.';
  const words = sentence.split(' ');
  if (words.length > 1000) return 'sentence has at most 1000 words.';
  if (words.some(word => word.length > 1000)) return 'Each word has at most 1000 letters.';
  return null;
}

