function replaceWords(dictionary, sentence) {
  const trie = { children: new Map(), root: null };
  for (const root of dictionary) {
    let node = trie;
    for (const letter of root) {
      if (!node.children.has(letter)) {
        node.children.set(letter, { children: new Map(), root: null });
      }
      node = node.children.get(letter);
    }
    node.root = root;
  }

  const words = sentence.split(' ');
  for (let i = 0; i < words.length; i++) {
    let node = trie;
    for (const letter of words[i]) {
      node = node.children.get(letter);
      if (node === undefined || node.root !== null) {
        break;
      }
    }
    if (node !== undefined && node.root !== null) {
      words[i] = node.root;
    }
  }
  return words.join(' ');
}

