function replaceWords(dictionary, sentence) {
  return sentence.split(' ').map(word => {
    let best = word;
    for (const root of dictionary) {
      if (word.startsWith(root) && root.length < best.length) best = root;
    }
    return best;
  }).join(' ');
}

