function generate(rand, size) {
  const randomWord = (alphabet, low, high) => {
    const length = low + Math.floor(rand() * (high - low + 1));
    let word = '';
    for (let i = 0; i < length; i++) word += alphabet[Math.floor(rand() * alphabet.length)];
    return word;
  };
  if (size === 'small') {
    const alphabet = rand() < 0.5 ? 'ab' : 'abc';
    const dictionary = Array.from({ length: 1 + Math.floor(rand() * 5) }, () => randomWord(alphabet, 1, 3));
    const words = Array.from({ length: 1 + Math.floor(rand() * 6) }, () => {
      if (rand() < 0.5) return dictionary[Math.floor(rand() * dictionary.length)] + randomWord(alphabet, 0, 3);
      return randomWord(alphabet, 1, 5);
    });
    return [dictionary, words.join(' ')];
  }
  const alphabet = 'abcdefghij';
  const dictionary = Array.from({ length: 300 + Math.floor(rand() * 701) }, () => randomWord(alphabet, 2, 7));
  const words = [];
  let length = -1;
  while (words.length < 1000) {
    let word;
    const r = rand();
    if (r < 0.5) word = dictionary[Math.floor(rand() * dictionary.length)] + randomWord(alphabet, 0, 5);
    else if (r < 0.98) word = randomWord(rand() < 0.5 ? alphabet : 'abcdefghijklmnopqrstuvwxyz', 1, 8);
    else word = randomWord(alphabet, 100, 400);
    if (length + 1 + word.length > 10000) break;
    words.push(word);
    length += 1 + word.length;
  }
  return [dictionary, words.join(' ')];
}
